def myheurdiving_helper(mayrounddown, mayroundup, candsfrac, candsol, nlocksdown, nlocksup, obj, objnorm, pscostdown, pscostup, rootsolval, nNonz, isBinary):
    score = 0.0
    roundup = False

    # Base scoring components
    if isBinary:
        score += obj * (1 - candsfrac)  # Favor binary solution closeness
    else:
        score += objnorm * (1 - candsfrac)  # Normalized objective consideration

    # Penalize if unable to round down or up
    if not mayrounddown:
        score -= 10  # Arbitrary penalty if rounding down is not feasible
    if not mayroundup:
        score -= 10  # Arbitrary penalty if rounding up is not feasible

    # Consider pseudo costs
    if mayrounddown and nlocksdown > 0:
        score += pscostdown * (1 - candsfrac)  # Incentivize rounding down if beneficial
    if mayroundup and nlocksup > 0:
        score += pscostup * candsfrac  # Incentivize rounding up if beneficial

    # Factor in rootsolval to favor solutions close to root node values
    if rootsolval > 0:
        if candsol > rootsolval:
            score += (candsol - rootsolval)  # Better to keep the solution below root
        else:
            score -= (rootsolval - candsol)  # Penalize moving away from the root

    # Decide rounding direction based on score
    if score > 0:
        roundup = True  # If the score is positive, prefer rounding up

    return score, roundup
